'use strict';
window.KANA_ROWS = [
 ['Vowels','あいうえお','アイウエオ',['a','i','u','e','o']],
 ['K row','かきくけこ','カキクケコ',['ka','ki','ku','ke','ko']],
 ['S row','さしすせそ','サシスセソ',['sa','shi','su','se','so']],
 ['T row','たちつてと','タチツテト',['ta','chi','tsu','te','to']],
 ['N row','なにぬねの','ナニヌネノ',['na','ni','nu','ne','no']],
 ['H row','はひふへほ','ハヒフヘホ',['ha','hi','fu','he','ho']],
 ['M row','まみむめも','マミムメモ',['ma','mi','mu','me','mo']],
 ['Y row','やゆよ','ヤユヨ',['ya','yu','yo']],
 ['R row','らりるれろ','ラリルレロ',['ra','ri','ru','re','ro']],
 ['W + N','わをん','ワヲン',['wa','o','n']]
];
const card=(jp,reading,en,my,speech=jp)=>({jp,reading,en,my,speech});
const words=(rows)=>rows.map(r=>card(...r));
const lessons=[];
for(const [script,idx,prefix] of [['Hiragana',1,'hira'],['Katakana',2,'kata']]){
 KANA_ROWS.forEach((r,i)=>lessons.push({id:`${prefix}-${i}`,name:`${script} · ${r[0]} — ${r[idx]}`,stage:'Foundation',noteEn:script==='Hiragana'?'Say each sound clearly. し = shi, ち = chi, つ = tsu, ふ = fu. を is usually pronounced “o”.':'Katakana represents the same basic sounds as hiragana. Watch the differences between シ / ツ and ソ / ン.',noteMy:script==='Hiragana'?'အသံတစ်ခုစီကို ရှင်းရှင်းထွက်ပါ။ し = shi၊ ち = chi၊ つ = tsu၊ ふ = fu ဖြစ်ပါတယ်။':'ကတကနနဲ့ ဟီရဂနရဲ့ အခြေခံအသံတွေ တူပါတယ်။ シ / ツ နဲ့ ソ / ン ကို သေချာခွဲကြည့်ပါ။',cards:[...r[idx]].map((k,j)=>card(k,r[3][j],`${r[3][j]} sound`,'အသံထွက် လေ့ကျင့်ပါ။'))}));
}
lessons.push(
 {id:'hira-vowel-words',name:'Hiragana · First words',stage:'Foundation',cards:words([['あい','a-i','love','အချစ်'],['うえ','u-e','above / up','အပေါ်'],['いえ','i-e','house','အိမ်'],['あお','a-o','blue','အပြာ'],['いい','i-i','good','ကောင်းသော']])},
 {id:'hira-ks-words',name:'Hiragana · K & S row words',stage:'Foundation',cards:words([['かお','ka-o','face','မျက်နှာ'],['いけ','i-ke','pond','ရေကန်'],['きく','ki-ku','to listen','နားထောင်သည်'],['すし','su-shi','sushi','ဆူရှီ'],['かさ','ka-sa','umbrella','ထီး'],['あし','a-shi','foot / leg','ခြေထောက်'],['そこ','so-ko','there','အဲဒီနေရာ']])},
 {id:'hira-t-words',name:'Hiragana · T row words — your next step',stage:'Foundation',noteEn:'ち is chi. つ is tsu. Say tsu as one short sound. In とけい, the “ei” often sounds like a long “e”.',noteMy:'ち ကို chi၊ つ ကို tsu လို့ ဖတ်ပါ။ tsu ကို တိုတို တစ်သံတည်း ထွက်ပါ။ とけい မှာ ei ကို e အသံရှည်လို ကြားရတတ်ပါတယ်။',cards:words([['たこ','ta-ko','octopus','ရေဘဝဲ'],['ちかてつ','chi-ka-te-tsu','subway','မြေအောက်ရထား'],['つき','tsu-ki','moon','လ'],['て','te','hand','လက်'],['とけい','to-ke-i','clock / watch','နာရီ']])},
 {id:'hira-more-words',name:'Hiragana · Everyday words',stage:'Foundation',cards:words([['ねこ','ne-ko','cat','ကြောင်'],['いぬ','i-nu','dog','ခွေး'],['はな','ha-na','flower','ပန်း','花'],['ふね','fu-ne','boat','လှေ'],['みず','mi-zu','water','ရေ'],['やま','ya-ma','mountain','တောင်'],['ゆき','yu-ki','snow','နှင်း'],['くるま','ku-ru-ma','car','ကား'],['ほん','ho-n','book','စာအုပ်']])},
 {id:'kata-words',name:'Katakana · Everyday words',stage:'Foundation',noteEn:'The mark ー makes the previous vowel longer. コーヒー has two long vowels. Give each one time.',noteMy:'ー က ရှေ့က သရသံကို ရှည်စေပါတယ်။ コーヒー မှာ သရသံရှည် နှစ်ခု ပါပါတယ်။',cards:words([['カメラ','ka-me-ra','camera','ကင်မရာ'],['テレビ','te-re-bi','television','တီဗီ'],['ラジオ','ra-ji-o','radio','ရေဒီယို'],['コーヒー','kō-hī','coffee','ကော်ဖီ'],['バス','ba-su','bus','ဘတ်စ်ကား'],['タクシー','ta-ku-shī','taxi','တက္ကစီ'],['パン','pa-n','bread','ပေါင်မုန့်']])},
 {id:'sound-changes',name:'Hiragana · Sound marks & combinations',stage:'Foundation',noteEn:'゛changes sounds (か → が). ゜makes the P sounds (は → ぱ). A small ゃ, ゅ or ょ joins the previous sound.',noteMy:'゛ ထည့်ရင် အသံပြောင်းပါတယ်။ ဥပမာ か → が။ ゜ ထည့်ရင် P အသံဖြစ်ပါတယ်။ ဥပမာ は → ぱ။',cards:words([['が','ga','voiced ka → ga','အသံပြောင်း လေ့ကျင့်ပါ။'],['ざ','za','voiced sa → za','အသံပြောင်း လေ့ကျင့်ပါ။'],['だ','da','voiced ta → da','အသံပြောင်း လေ့ကျင့်ပါ။'],['ば','ba','voiced ha → ba','အသံပြောင်း လေ့ကျင့်ပါ။'],['ぱ','pa','ha → pa','အသံပြောင်း လေ့ကျင့်ပါ။'],['きゃ','kya','one combined sound','ပေါင်းစပ်အသံ တစ်သံ'],['しゅ','shu','one combined sound','ပေါင်းစပ်အသံ တစ်သံ'],['ちょ','cho','one combined sound','ပေါင်းစပ်အသံ တစ်သံ'],['きって','kit-te','postage stamp — pause briefly at っ','စာပို့တံဆိပ်ခေါင်း']])},
 {id:'greetings',name:'N5 practice · Greetings',stage:'N5 practice',cards:words([['こんにちは。','konnichiwa','Hello.','မင်္ဂလာပါ။'],['おはようございます。','ohayō gozaimasu','Good morning.','မင်္ဂလာနံနက်ခင်းပါ။'],['ありがとうございます。','arigatō gozaimasu','Thank you.','ကျေးဇူးတင်ပါတယ်။'],['すみません。','sumimasen','Excuse me. / I’m sorry.','တစ်ဆိတ်လောက်။ / တောင်းပန်ပါတယ်။'],['さようなら。','sayōnara','Goodbye.','နှုတ်ဆက်ပါတယ်။']])},
 {id:'n5-phrases',name:'N5 practice · Introduce yourself',stage:'N5 practice',noteEn:'は marks the topic and is pronounced “wa” here. Listen once, repeat slowly, then try at normal speed.',noteMy:'ဒီဝါကျတွေမှာ は က အကြောင်းအရာကို ဖော်ပြပြီး wa လို့ ဖတ်ပါတယ်။ အရင်ဖြည်းဖြည်း လိုက်ပြောပါ။',cards:words([['私は学生です。','わたしは がくせいです。','I am a student.','ကျွန်တော်/ကျွန်မက ကျောင်းသား/ကျောင်းသူပါ။'],['日本語を勉強しています。','にほんごを べんきょうしています。','I am studying Japanese.','ဂျပန်စာ လေ့လာနေပါတယ်။'],['もう一度言ってください。','もういちど いってください。','Please say it again.','နောက်တစ်ခေါက် ပြောပေးပါ။'],['よろしくお願いします。','よろしく おねがいします。','Nice to meet you. (At an introduction.)','တွေ့ရတာ ဝမ်းသာပါတယ်။ (မိတ်ဆက်ချိန်တွင်)']])},
 {id:'n4-phrases',name:'N4 practice · Keep a conversation going',stage:'N4 practice',cards:words([['日本語を話すことができます。','にほんごを はなすことが できます。','I can speak Japanese.','ဂျပန်လို ပြောနိုင်ပါတယ်။'],['ゆっくり話してもらえませんか。','ゆっくり はなして もらえませんか。','Could you speak slowly?','ဖြည်းဖြည်း ပြောပေးလို့ရမလား။'],['毎日、練習しようと思っています。','まいにち、れんしゅうしようと おもっています。','I intend to practise every day.','နေ့တိုင်း လေ့ကျင့်ဖို့ စိတ်ကူးထားပါတယ်။'],['日本に行ったことがあります。','にほんに いったことが あります。','I have been to Japan.','ဂျပန်ကို ရောက်ဖူးပါတယ်။']])},
 {id:'n3-phrases',name:'N3 practice · Express your ideas',stage:'N3 practice',noteEn:'Practise in short chunks, then connect them. These are selected speaking exercises, not a complete N3 course.',noteMy:'ဝါကျကို အပိုင်းတိုတို ခွဲလေ့ကျင့်ပြီး ပြန်ဆက်ပြောပါ။ ဒါတွေက N3 သင်တန်းအပြည့်အစုံ မဟုတ်ဘဲ ရွေးထားတဲ့ လေ့ကျင့်ခန်းတွေပါ။',cards:words([['忘れないように、毎日復習しています。','わすれないように、まいにち ふくしゅうしています。','I review every day so I don’t forget.','မမေ့အောင် နေ့တိုင်း ပြန်လေ့လာပါတယ်။'],['もう一度説明していただけますか。','もういちど せつめいして いただけますか。','Could you explain it once more?','နောက်တစ်ခေါက် ရှင်းပြပေးနိုင်မလား။'],['練習すればするほど、自信がつきます。','れんしゅうすれば するほど、じしんが つきます。','The more I practise, the more confident I become.','လေ့ကျင့်လေလေ၊ ကိုယ့်ကိုယ်ကို ယုံကြည်မှု ပိုရှိလာလေလေပါ။'],['天気予報によると、明日は雨だそうです。','てんきよほうに よると、あしたは あめだそうです。','According to the forecast, it will rain tomorrow.','မိုးလေဝသခန့်မှန်းချက်အရ မနက်ဖြန် မိုးရွာမယ်လို့ ဆိုပါတယ်။']])}
);
window.LESSONS=lessons;
